+const MOTIVO_MIN_CARACTERES = 10; // lección L-motivo-minimo-auditoria
+
+// Ajuste por recuento (ADR-001): si lo contado difiere del stock calculado, agrega un movimiento
+// por la diferencia; si no difiere, devuelve la lista sin cambios. Nunca guarda un campo `stock`.
+export function ajustarInventario(movimientos, { articulo, almacen, cantidadContada, motivo } = {}) {
+  if (!articulo || !almacen) throw new Error("El ajuste necesita artículo y almacén");
+  if (!Number.isInteger(cantidadContada) || cantidadContada < 0)
+    throw new RangeError("La cantidad contada debe ser un entero mayor o igual a cero");
+  const motivoLimpio = typeof motivo === "string" ? motivo.trim() : "";
+  if (motivoLimpio.length < MOTIVO_MIN_CARACTERES)
+    throw new Error(`El motivo debe tener al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+
+  const diferencia = cantidadContada - stock(movimientos, articulo, almacen);
+  if (diferencia === 0) return movimientos;
+  return registrarMovimiento(movimientos, {
+    tipo: diferencia > 0 ? "ingreso" : "egreso",
+    articulo,
+    almacen,
+    cantidad: Math.abs(diferencia),
+    motivo: motivoLimpio,
+  });
+}
